(assert (= "1.12.6" (clojure-version)))
(def receive-double (fn [^double x] x))
(let [source "(let [^long x (identity 5.5)] [x (+ x 1) (inc x) (dec x) (- x) (+ x) (* x)])" expected "[5.5 6 6 4 -5 5.5 5.5]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [^double x (identity 5)] [x (+ x 1) (inc x) (dec x)])" expected "[5 6.0 6.0 4.0]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [^long x (identity 0.5)] [(zero? x) (zero? (identity x)) (== x 0.5) (= x 0.5) (< x 0.5)])" expected "[true false false true true]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [^long x (identity 5.5)] [(bit-and x 1) (quot x 2) (rem x 2) (mod x 2) (abs x)])" expected "[1 2 1 1.5 5]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [^long x (identity 5.5)] [(double x) (float x) (int x)])" expected "[5.0 5.0 5]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [^long x (identity 5.5)] (receive-double x))" expected "5.5" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [^long x (identity 5.5) f receive-double] (f x))" expected "5.5" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [^long x (identity 5.5)] ((fn [^double y] y) x))" expected "5.5" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [^long x (identity 5.5)] [(/ x 1) (/ x)])" expected "[5 0.18181818181818182]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(loop [^long x (identity 5.5) n 0] (if (zero? n) (recur (identity 7.5) 1) [x (+ x 1)]))" expected "[7.5 8]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [^long x (identity 5.5) f (fn [] [x (+ x 1)])] (f))" expected "[5.5 6]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [^long x (identity 5.5) y x] [x y (+ y 1)])" expected "[5.5 5.5 6]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [^long x (identity 5.5)] [(if true x 1) (do x) x])" expected "[5.5 5.5 5.5]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [^long x (identity 5.5) y (if true x 1)] [x y])" expected "[5.5 5.5]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [^long x (identity 5.5)] ((fn ^double [] x)))" expected "5.5" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
